PHP >= 8.0 / Composer composer require erikwang2013/messaging-php use Erikwang2013\Messaging\Contract\Message;
use Erikwang2013\Messaging\Contract\ReceiveOptions;
use Erikwang2013\Messaging\Manager;

$mq = new Manager([
    'default' => 'redis',
    'connections' => [
        'redis' => [
            'driver' => 'redis',
            'host' => '127.0.0.1',
            'port' => 6379,
            'group' => 'orders',
        ],
    ],
]);

$connection = $mq->connection();
$connection->publish('orders', Message::json(['id' => 1]));

while ($message = $connection->receive('orders', new ReceiveOptions(timeoutMs: 5000))) {
    $message->ack();
}
